class LinkedList:
    def __init__(self):
        self.head = None  # _at is used to denote the attribute name

    def append(self, value):
        new_node = _Node(value)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current._next:
                current = current._next
            current._next = new_node

    def prepend(self, value):
        new_node = _Node(value)
        new_node._next = self.head
        self.head = new_node

    def delete(self, value):
        if not self.head:
            return

        if self.head._value == value:
            self.head = self.head._next
            return

        current = self.head
        while current._next:
            if current._next._value == value:
                current._next = current._next._next
                return
            current = current._next

    def search(self, value):
        current = self.head
        while current:
            if current._value == value:
                return True
            current = current._next
        return False

    def length(self):
        count = 0
        current = self.head
        while current:
            count += 1
            current = current._next
        return count

    def print_list(self):
        current = self.head
        while current:
            print(current._value, end=" -> ")
            current = current._next
        print("None")

class _Node:
    def __init__(self, value):
        self._value = value
        self._next = None
